import{_ as e,o,c as l,ac as r}from"./chunks/framework.CrIZQWiq.js";const p=JSON.parse('{"title":"lmulator","description":"模拟器插件","frontmatter":{"tag":["vscode插件"],"title":"lmulator","description":"模拟器插件"},"headers":[],"relativePath":"articles/产品/lmulator.md","filePath":"articles/产品/lmulator.md","lastUpdated":null}'),i={name:"articles/产品/lmulator.md"};function t(d,a,n,c,s,u){return o(),l("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1781410144803"},a[0]||(a[0]=[r('<h1 id="lmulator-在-vs-code-里管理移动模拟器、看画面、跑项目" tabindex="-1">LMulator：在 VS Code 里管理移动模拟器、看画面、跑项目 <a class="header-anchor" href="#lmulator-在-vs-code-里管理移动模拟器、看画面、跑项目" aria-label="Permalink to &quot;LMulator：在 VS Code 里管理移动模拟器、看画面、跑项目&quot;">​</a></h1><blockquote><p>移动开发不必再周旋于 Android Studio、Xcode 和命令行之间。</p></blockquote><hr><h2 id="一句话介绍" tabindex="-1">一句话介绍 <a class="header-anchor" href="#一句话介绍" aria-label="Permalink to &quot;一句话介绍&quot;">​</a></h2><p><strong>LMulator</strong> 是一款在 VS Code 中管理 Android / iOS 模拟器、嵌入模拟器画面并一键运行移动端项目的插件。</p><hr><h2 id="下载安装" tabindex="-1">下载安装 <a class="header-anchor" href="#下载安装" aria-label="Permalink to &quot;下载安装&quot;">​</a></h2><ul><li><strong>VS Code Marketplace</strong>：<a href="https://marketplace.visualstudio.com/items?itemName=leeb.lmulator" target="_blank" rel="noreferrer">https://marketplace.visualstudio.com/items?itemName=leeb.lmulator</a></li><li><strong>一键安装</strong>（需本地已安装 VS Code）：<a href="vscode:extension/leeb.lmulator" target="_blank" rel="noreferrer">vscode:extension/leeb.lmulator</a></li></ul><hr><h2 id="为什么需要它" tabindex="-1">为什么需要它？ <a class="header-anchor" href="#为什么需要它" aria-label="Permalink to &quot;为什么需要它？&quot;">​</a></h2><p>做移动开发的同学，往往要面对一套复杂的工具链：</p><ul><li>启动模拟器要开 Android Studio 或 Xcode；</li><li>运行项目要记不同框架的命令；</li><li>想看一下模拟器画面，得把窗口切来切去；</li><li>Flutter、React Native、Ionic、Capacitor、uni-app……每个项目启动方式都不一样；</li><li>日志窗口、终端、IDE、模拟器挤满屏幕，手忙脚乱。</li></ul><p>LMulator 的目标是：<strong>把模拟器管理、项目运行、日志查看都集中在 VS Code 里完成</strong>，让你少切几次窗口，多写几行代码。</p><hr><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><h3 id="📱-左侧活动栏面板" tabindex="-1">📱 左侧活动栏面板 <a class="header-anchor" href="#📱-左侧活动栏面板" aria-label="Permalink to &quot;📱 左侧活动栏面板&quot;">​</a></h3><p>点击 VS Code 左侧活动栏的手机图标，打开 LMulator 面板。面板分为三个标签页：</p><ul><li><strong>Android</strong>：管理 Android AVD 和已连接设备；</li><li><strong>iOS</strong>：管理 iOS Simulator（macOS）；</li><li><strong>环境</strong>：查看和配置 SDK 路径等环境信息。</li></ul><h3 id="📋-设备列表" tabindex="-1">📋 设备列表 <a class="header-anchor" href="#📋-设备列表" aria-label="Permalink to &quot;📋 设备列表&quot;">​</a></h3><p>自动列出可用的 Android AVD、已连接的 Android 设备，以及 iOS Simulator，方便你快速选择目标设备。</p><h3 id="🖥️-嵌入模拟器画面" tabindex="-1">🖥️ 嵌入模拟器画面 <a class="header-anchor" href="#🖥️-嵌入模拟器画面" aria-label="Permalink to &quot;🖥️ 嵌入模拟器画面&quot;">​</a></h3><p>无需离开 VS Code，就能在面板内实时查看模拟器屏幕：</p><ul><li><strong>Android</strong>：通过 <code>adb exec-out screencap -p</code> 定时截图刷新；</li><li><strong>iOS</strong>：通过 <code>xcrun simctl io &lt;udid&gt; screenshot</code> 定时截图刷新。</li></ul><h3 id="👆-点击画面控制-android-模拟器" tabindex="-1">👆 点击画面控制 Android 模拟器 <a class="header-anchor" href="#👆-点击画面控制-android-模拟器" aria-label="Permalink to &quot;👆 点击画面控制 Android 模拟器&quot;">​</a></h3><p>在预览画面上点击，插件会自动计算缩放比例，把坐标映射为真实屏幕坐标，并通过 <code>adb shell input tap</code> 发送触摸事件，真正做到「看着画面就能操作」。</p><h3 id="▶️-一键启动-停止" tabindex="-1">▶️ 一键启动 / 停止 <a class="header-anchor" href="#▶️-一键启动-停止" aria-label="Permalink to &quot;▶️ 一键启动 / 停止&quot;">​</a></h3><ul><li>启动 Android AVD 或 iOS Simulator；</li><li>关闭正在运行的设备。</li></ul><h3 id="🚀-启动并运行" tabindex="-1">🚀 启动并运行 <a class="header-anchor" href="#🚀-启动并运行" aria-label="Permalink to &quot;🚀 启动并运行&quot;">​</a></h3><p>一键完成「启动模拟器 → 等待设备就绪 → 运行当前项目」的完整流程。</p><h3 id="🧠-自动识别项目类型" tabindex="-1">🧠 自动识别项目类型 <a class="header-anchor" href="#🧠-自动识别项目类型" aria-label="Permalink to &quot;🧠 自动识别项目类型&quot;">​</a></h3><p>LMulator 会根据项目文件特征判断你正在开发哪类应用：</p><ul><li><strong>Flutter</strong>：<code>pubspec.yaml</code>；</li><li><strong>React Native</strong>：<code>react-native.config.js</code>、<code>metro.config.js</code>、<code>package.json</code> 依赖；</li><li><strong>Ionic / Cordova</strong>：<code>ionic.config.json</code>；</li><li><strong>Capacitor</strong>：<code>capacitor.config.json</code>；</li><li><strong>uni-app</strong>：<code>manifest.json</code> + <code>pages.json</code>。</li></ul><h3 id="🛠️-自动生成运行命令" tabindex="-1">🛠️ 自动生成运行命令 <a class="header-anchor" href="#🛠️-自动生成运行命令" aria-label="Permalink to &quot;🛠️ 自动生成运行命令&quot;">​</a></h3><p>根据项目类型和目标设备，自动生成对应命令：</p><ul><li>Flutter：<code>flutter run -d &lt;device&gt;</code></li><li>React Native：<code>npx react-native run-android --deviceId &lt;id&gt;</code></li><li>Capacitor：<code>npx cap run android --target &lt;id&gt;</code></li><li>Ionic：<code>ionic cordova run android --target=&lt;id&gt;</code></li></ul><h3 id="⚙️-自定义命令模板" tabindex="-1">⚙️ 自定义命令模板 <a class="header-anchor" href="#⚙️-自定义命令模板" aria-label="Permalink to &quot;⚙️ 自定义命令模板&quot;">​</a></h3><p>如果默认命令不满足需求，可以在设置中自定义：</p><ul><li><code>lmulator.runCommand.android</code></li><li><code>lmulator.runCommand.ios</code></li></ul><h3 id="📜-实时日志面板" tabindex="-1">📜 实时日志面板 <a class="header-anchor" href="#📜-实时日志面板" aria-label="Permalink to &quot;📜 实时日志面板&quot;">​</a></h3><p>运行命令的 <code>stdout</code> 和 <code>stderr</code> 会流式显示在下方面板中，方便你实时查看应用输出。</p><h3 id="🔧-sdk-配置" tabindex="-1">🔧 SDK 配置 <a class="header-anchor" href="#🔧-sdk-配置" aria-label="Permalink to &quot;🔧 SDK 配置&quot;">​</a></h3><p>支持手动指定 Android SDK 根目录，解决环境变量未配置或路径特殊的情况。</p><hr><h2 id="使用流程" tabindex="-1">使用流程 <a class="header-anchor" href="#使用流程" aria-label="Permalink to &quot;使用流程&quot;">​</a></h2><ol><li>安装插件后点击左侧活动栏的 LMulator 图标；</li><li>如需要，点击「设置 SDK」指定 Android SDK 路径；</li><li>在 Android / iOS 标签页查看可用设备列表；</li><li>点击「启动」启动模拟器，或「启动并运行」启动后直接运行项目；</li><li>设备运行后点击「画面」，在面板内嵌入实时屏幕；</li><li>点击「📋 命令」查看自动生成的运行命令，可复制或点击「运行」直接执行；</li><li>在下方面板查看实时运行日志。</li></ol><hr><h2 id="技术亮点" tabindex="-1">技术亮点 <a class="header-anchor" href="#技术亮点" aria-label="Permalink to &quot;技术亮点&quot;">​</a></h2><ul><li><strong>直接调用系统 CLI</strong>：<code>emulator</code>、<code>adb</code>、<code>xcrun simctl</code>，无需额外守护进程；</li><li><strong>定时截图流实现画面嵌入</strong>，Android 700ms、iOS 1000ms 刷新；</li><li><strong>Android 点击回传</strong>通过计算预览图与实际屏幕的缩放比例，映射为真实坐标后发送 <code>adb shell input tap</code>；</li><li><strong>项目类型自动检测</strong>，通过多种文件特征组合判断框架类型；</li><li><strong>子进程 <code>spawn</code> 管理</strong>，支持运行命令的流式日志输出与进程清理；</li><li><strong>跨平台适配</strong>，Windows 下自动为命令追加 <code>.exe</code> 后缀。</li></ul><hr><h2 id="适合谁用" tabindex="-1">适合谁用？ <a class="header-anchor" href="#适合谁用" aria-label="Permalink to &quot;适合谁用？&quot;">​</a></h2><ul><li>Flutter、React Native、Ionic / Cordova、Capacitor、uni-app 开发者；</li><li>需要在编码时持续查看模拟器画面的调试场景；</li><li>频繁切换 Android 与 iOS 模拟器的多端开发者；</li><li>希望把模拟器管理、项目运行、日志查看集中在 VS Code 内的团队。</li></ul><hr><h2 id="典型场景" tabindex="-1">典型场景 <a class="header-anchor" href="#典型场景" aria-label="Permalink to &quot;典型场景&quot;">​</a></h2><ul><li>在 VS Code 内启动 Android 模拟器并预览 Flutter 应用；</li><li>在 macOS 上启动 iOS Simulator 调试 React Native 项目；</li><li>边看模拟器画面边查看实时日志，快速定位问题；</li><li>多个移动项目之间切换，无需记忆不同的启动命令。</li></ul><hr><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>LMulator 想做的事情很简单：<strong>让移动开发的日常操作更集中在编辑器里完成</strong>。模拟器、命令、日志、画面，本该都在你写代码的地方。</p><p>如果你也厌倦了在不同工具之间反复横跳，LMulator 可能会让你的移动开发流程顺畅许多。</p><blockquote><p>👉 <a href="https://marketplace.visualstudio.com/items?itemName=leeb.lmulator" target="_blank" rel="noreferrer">点击前往 VS Code Marketplace 下载 LMulator</a></p></blockquote>',59)]))}const m=e(i,[["render",t]]);export{p as __pageData,m as default};
